import{d as g,C as n,o as d,c as h,E as i,a3 as o}from"./chunks/framework.D4-ViStF.js";const c=JSON.parse('{"title":"巽为风","description":"巽为风，巽上巽下","frontmatter":{"title":"巽为风","description":"巽为风，巽上巽下","category":"hexagram","aliases":["巽","巽为风"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-57.md","filePath":"yijing/hexagrams/hexagram-57.md","lastUpdated":1787800334000}'),p={name:"yijing/hexagrams/hexagram-57.md"},b=g({...p,setup(u){const e=[{id:"xun",term:"巽",pinyin:"xùn",meaning:"入、顺、逊。卦名。风无孔不入，引申为谦逊顺从、因势而入。",context:"巽卦之名：两风相随，重巽以申命。"},{id:"jintui",term:"进退",pinyin:"jìn tuì",meaning:"进与退、迟疑不决。",context:"初六「进退，利武人之贞」：迟疑时用果决定住。"},{id:"wurenzhizhen",term:"武人之贞",pinyin:"wǔ rén zhī zhēn",meaning:"武人的刚决守正。给柔顺安一根果决的脊梁。",context:"初六：巽柔之极，须以武人之贞治志。"},{id:"chuangxia",term:"巽在床下",pinyin:"xùn zài chuáng xià",meaning:"低伏在床下，谦卑到不能再低。",context:"九二主动低伏是起点；上九倒下不起是放弃。"},{id:"shiwu",term:"史巫",pinyin:"shǐ wū",meaning:"祝史与巫觋，古代沟通神明之人。",context:"九二「用史巫纷若」：以至诚沟通天地。"},{id:"fenruo",term:"纷若",pinyin:"fēn ruò",meaning:"频频叩祷、至诚恳切的样子。",context:"九二「用史巫纷若，吉，无咎」：至诚至极，反得其吉。"},{id:"pinxun",term:"频巽",pinyin:"pín xùn",meaning:"频频勉强顺从；也通「颦」，皱着眉头装柔。",context:"九三「频巽，吝」：装出来的柔，撑不过第三遍。"},{id:"tianhuoshipin",term:"田获三品",pinyin:"tián huò sān pǐn",meaning:"田猎获三类猎物（干豆、宾客、充庖），喻大有所获。",context:"六四「悔亡，田获三品」：行动把悔缴获成收获。"},{id:"xianggeng",term:"先庚三日",pinyin:"xiān gēng sān rì",meaning:"变革之前，先反复申明。庚属金、主变革。",context:"九五：变革之前先申明，之后要巩固。"},{id:"hougeng",term:"后庚三日",pinyin:"hòu gēng sān rì",meaning:"变革之后，再反复巩固。",context:"九五「无初有终」：开头难看没关系，巩固好就有终。"},{id:"sangqizifu",term:"丧其资斧",pinyin:"sàng qí zī fǔ",meaning:"资为钱财资本，斧为决断工具；连同决断力一起丢失。",context:"上九「丧其资斧，贞凶」：外力可失，内力不可丢。"},{id:"zhenxiong",term:"贞凶",pinyin:"zhēn xiōng",meaning:"守而不变、明知当断却不断，执着于错误的路径而致凶。",context:"上九「贞凶」：凶的不是失去，是放弃行动本身。"},{id:"shenming",term:"申命",pinyin:"shēn mìng",meaning:"反复申明命令。",context:"象传「随风，巽，君子以申命行事」：一遍一遍把意图说透。"}],r=[{position:"初六",type:"yin",text:"进退，利武人之贞。",xiang:"进退，志疑也。利武人之贞，志治也。",textModern:"进退迟疑，用武人的刚决守住心志，吉祥。",xiangModern:"进退迟疑，是因为志向动摇；用武人之贞，是让志意重新归正。"},{position:"九二",type:"yang",text:"巽在床下，用史巫纷若，吉，无咎。",xiang:"纷若之吉，得中也。",textModern:"谦卑地伏在床下，以至诚频频沟通，吉祥，没有灾祸。",xiangModern:"至诚之吉，是因为九二刚柔得中。"},{position:"九三",type:"yang",text:"频巽，吝。",xiang:"频巽之吝，志穷也。",textModern:"频频勉强顺从，心有憾惜。",xiangModern:"勉强装柔的憾惜，是因为心志穷竭、进退无据。"},{position:"六四",type:"yin",text:"悔亡，田获三品。",xiang:"田获三品，有功也。",textModern:"悔恨消失，田猎大有收获。",xiangModern:"田猎大获，是因为有实实在在的功劳。"},{position:"九五",type:"yang",text:"贞吉，悔亡，无不利。无初有终。先庚三日，后庚三日，吉。",xiang:"九五之吉，位正中也。",textModern:"守正则吉，悔恨消失，无所不利。开头不顺，结局有成；变革之前反复申明，之后反复巩固，吉祥。",xiangModern:"九五之吉，是因为居中得正，是变革的掌舵者。"},{position:"上九",type:"yang",text:"巽在床下，丧其资斧，贞凶。",xiang:"巽在床下，上穷也。丧其资斧，正乎凶也。",textModern:"伏在床下，连同决断力一起丢失，守此不变则凶。",xiangModern:"伏在床下，是柔道走到尽头；丢失决断力，正是走向凶途。"}];return(m,t)=>{const a=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),s=n("DaoKeywordCards");return d(),h("div",null,[i(a,{name:"巽为风",fullName:"巽为风",upper:"☴",lower:"☴",guaCi:"巽，小亨。利有攸往，利见大人。",pinyin:["xùn","wéi","fēng"],element:"木",direction:"东南",virtue:"入",insight:"两风相随，无孔不入；柔顺入物，武人之心是根。",guaSlug:"57xunweifeng",lines:r}),t[0]||(t[0]=o('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>随风，巽。君子以申命行事。</p><ul><li><strong>随风，巽</strong> —— 风与风相随，前风去而后风来，正是巽顺而入、层层传递之象。巽不是一阵风，是不断的跟随。</li><li><strong>君子以申命行事</strong> —— 君子由此领悟：要反复申明号令、顺入民心，让意志化开、落地成事。</li></ul><p>「申命行事」——<strong>申</strong>是反复叮咛、申明；<strong>命</strong>是命令、旨意；<strong>行</strong>是推行；<strong>事</strong>是成事。申命，是把话说到人心里去，一遍一遍；行事，是把说透的话做成事。</p><p>分形结构：</p><ul><li>申命（风起）→ 微观：把话说透，反复沟通</li><li>行事（风行）→ 宏观：把意志落地，顺势成事</li></ul><blockquote><p><strong>随风之入</strong>：风不是靠蛮力改天换地，是靠一遍一遍地吹。申命不是唠叨，是让意图渗透进每一个缝隙，直到人心自己转向。</p></blockquote><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>重巽以申命。刚巽乎中正而志行，柔皆顺乎刚。是以小亨，利有攸往，利见大人。</p><p>逐句释义：</p><ul><li><strong>重巽以申命</strong> —— 两巽相叠（☴☴），如风随风，意味着一遍又一遍地申明号令。巽的功夫，在于重复。</li><li><strong>刚巽乎中正而志行</strong> —— 阳刚者（九二、九五）以巽顺之姿居于中正之位，志向得以施行。刚不是靠硬，是靠入。</li><li><strong>柔皆顺乎刚</strong> —— 初六、六四两阴爻都顺承阳刚。柔顺是为了依附正道，不是无原则地软。</li><li><strong>是以小亨，利有攸往，利见大人</strong> —— 所以是小亨，利于有所前往，利于遇见大人。巽的亨是「小亨」：不轰轰烈烈，却渗透得深远。</li></ul><blockquote><p><strong>小亨不小</strong>：巽之亨是渗透式的亨。风一吼即散，风之入物，胜在柔、在于续。柔得进去，才能走得远。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',13)),i(l,{element:"木",guaSlug:"57xunweifeng",glossary:e,items:r}),t[1]||(t[1]=o('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初六-·-进退-利武人之贞" tabindex="-1">初六 · 进退，利武人之贞 <a class="header-anchor" href="#初六-·-进退-利武人之贞" aria-label="Permalink to &quot;初六 · 进退，利武人之贞&quot;">​</a></h3><ul><li><strong>进退</strong> → 一会儿想进，一会儿想退，迟疑不决</li><li><strong>武人之贞</strong> → 武人的刚决守正；用武人的果决定住自己</li><li><strong>象曰「进退，志疑也」</strong> → 进退，是因为志向动摇；<strong>「利武人之贞，志治也」</strong> → 用武人之贞，是让志意重新归于治理</li></ul><p>初六阴居巽之最下，是巽柔的极致。柔到极致，最容易优柔寡断——进也怕、退也怕。卦给出的解药不是「更柔」，而是相反：<strong>利武人之贞</strong>，用武人的果决，给柔安一根脊梁。</p><blockquote><p>核心洞见：柔是手段，武人之心是根。初六这一爻，是把「武人之心」种进整卦的最早位置——巽的六个爻，从此都在守护这根。</p></blockquote><h3 id="九二-·-巽在床下-用史巫纷若-吉-无咎" tabindex="-1">九二 · 巽在床下，用史巫纷若，吉，无咎 <a class="header-anchor" href="#九二-·-巽在床下-用史巫纷若-吉-无咎" aria-label="Permalink to &quot;九二 · 巽在床下，用史巫纷若，吉，无咎&quot;">​</a></h3><ul><li><strong>巽在床下</strong> → 谦卑地伏在床下，低到不能再低</li><li><strong>史巫</strong> → 祝史与巫觋，古代沟通神明的人</li><li><strong>纷若</strong> → 频频叩祷、至诚恳切</li><li><strong>象曰「纷若之吉，得中也」</strong> → 至诚之吉，是因为九二阳居阴位、刚柔得中</li></ul><p>九二以刚质行柔道，又得中位。它的「床下」不是被压下去的，是自己伏下去的——主动蛰伏，是选择，不是认命。再配上「用史巫纷若」的至诚，谦卑就成了沟通天人的通道。</p><blockquote><p>核心洞见：九二的床下是<strong>起点</strong>——从未起身，主动低伏，柔而不失其志。这是智慧，不是窝囊。</p></blockquote><h3 id="九三-·-频巽-吝" tabindex="-1">九三 · 频巽，吝 <a class="header-anchor" href="#九三-·-频巽-吝" aria-label="Permalink to &quot;九三 · 频巽，吝&quot;">​</a></h3><ul><li><strong>频</strong> → 频繁、屡次；也通「颦」，皱眉头</li><li><strong>频巽</strong> → 一会儿顺从、一会儿又不甘，勉强地反复</li><li><strong>象曰「频巽之吝，志穷也」</strong> → 勉强装柔的憾惜，是因为心志穷竭、进退无据</li></ul><p>九三阳居阳位，过刚而不中，本不是能久屈之人。他勉强装柔，装几次就憋不住——频巽之吝，吝在反复。</p><blockquote><p>核心洞见：巽不是表演。装出来的柔，撑不过第三遍。</p></blockquote><h3 id="六四-·-悔亡-田获三品" tabindex="-1">六四 · 悔亡，田获三品 <a class="header-anchor" href="#六四-·-悔亡-田获三品" aria-label="Permalink to &quot;六四 · 悔亡，田获三品&quot;">​</a></h3><ul><li><strong>悔亡</strong> → 悔恨消失</li><li><strong>田获三品</strong> → 田猎获三类猎物（干豆、宾客、充庖），喻大有所获</li><li><strong>象曰「田获三品，有功也」</strong> → 之所以大获，是因为有实功</li></ul><p>六四阴居阴位，得正；上承九五、下顺初六，是巽卦中柔用得最对的一爻。它先有过「悔」，但因为它真的去行动（田猎），悔就亡了。</p><blockquote><p>核心洞见：悔不可怕，悔而不动才可怕。用行动把悔「缴获」成收获。</p></blockquote><h3 id="九五-·-贞吉-悔亡-无不利。无初有终。先庚三日-后庚三日-吉" tabindex="-1">九五 · 贞吉，悔亡，无不利。无初有终。先庚三日，后庚三日，吉 <a class="header-anchor" href="#九五-·-贞吉-悔亡-无不利。无初有终。先庚三日-后庚三日-吉" aria-label="Permalink to &quot;九五 · 贞吉，悔亡，无不利。无初有终。先庚三日，后庚三日，吉&quot;">​</a></h3><ul><li><strong>贞吉，悔亡</strong> → 守正则吉，悔恨消失</li><li><strong>无初有终</strong> → 开头可能不顺，最终必有善终</li><li><strong>先庚三日，后庚三日</strong> → 庚属金、主变革；变之先反复申明（先庚三日），变之后反复巩固（后庚三日）</li><li><strong>象曰「九五之吉，位正中也」</strong> → 九五居中得正，是巽卦的君位、变革的掌舵者</li></ul><p>九五是巽卦之主：以刚居尊，却能巽顺入物。它讲的是一个完整的变革流程——<strong>觉察</strong>（贞吉）、<strong>行动</strong>（无不利）、<strong>巩固</strong>（后庚三日）。「无初有终」：开头难看没关系，只要按「先庚三日、后庚三日」的节奏把话申透、把事做稳。</p><blockquote><p>核心洞见：变革不是一锤子，是三段式——觉察在前，行动居中，巩固收尾。少一段，风就停在中途。</p></blockquote><h3 id="上九-·-巽在床下-丧其资斧-贞凶" tabindex="-1">上九 · 巽在床下，丧其资斧，贞凶 <a class="header-anchor" href="#上九-·-巽在床下-丧其资斧-贞凶" aria-label="Permalink to &quot;上九 · 巽在床下，丧其资斧，贞凶&quot;">​</a></h3><ul><li><strong>巽在床下</strong> → 又是床下，但这次是曾经起来过、又倒下去的床下</li><li><strong>丧其资斧</strong> → 资是钱财资本，斧是决断工具；连同决断力一起丢了</li><li><strong>贞凶</strong> → 明知当断却不断，执着于错误的柔顺，所以凶</li><li><strong>象曰「巽在床下，上穷也」</strong> → 居卦之极，柔道已走到尽头</li></ul><p>上九与九二同辞「巽在床下」，命运却相反。九二的床下是从未起身，主动低伏，是<strong>起点</strong>；上九的床下是曾经起身、又倒下去，是<strong>放弃</strong>。</p><p><strong>资斧六维</strong>：钱财、资本、凭依、工具——这些是外力，可以失去；决断力、行动力——这些是内力，不可被夺。上九丢的不是钱，是把斧头（决断力）一起扔了。</p><blockquote><p>核心洞见：贞凶的根源，是明知答案却不行动。凶的不是失去，是放弃行动本身。</p></blockquote><p><strong>九二 vs 上九——同辞异义</strong>：</p><table tabindex="0"><thead><tr><th>爻位</th><th>床下之意</th><th>本质</th><th>结局</th></tr></thead><tbody><tr><td>九二</td><td>从未起身，主动低伏</td><td>起点</td><td>吉，无咎</td></tr><tr><td>上九</td><td>曾经起身，又倒下去</td><td>放弃</td><td>贞凶</td></tr></tbody></table><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',29)),i(s,{title:"字词释义",items:[{term:"巽",pinyin:["xùn"],meaning:"入、顺、逊。卦名。风无孔不入，引申为谦逊顺从、因势而入。"},{term:"小亨",pinyin:["xiǎo","hēng"],meaning:"小有所亨通。巽之亨是渗透式的亨：不轰轰烈烈，却走得深远。"},{term:"申命",pinyin:["shēn","mìng"],meaning:"反复申明命令。「重巽以申命」：一遍一遍把意图说透。"},{term:"行事",pinyin:["xíng","shì"],meaning:"推行事功。把申明的话，做成落地的实事。"},{term:"进退",pinyin:["jìn","tuì"],meaning:"进与退、迟疑不决。象曰「进退，志疑也」。"},{term:"武人之贞",pinyin:["wǔ","rén","zhī","zhēn"],meaning:"武人的刚决守正。给柔顺安一根果决的脊梁。"},{term:"史巫",pinyin:["shǐ","wū"],meaning:"祝史与巫觋，古代沟通神明之人。"},{term:"纷若",pinyin:["fēn","ruò"],meaning:"频频叩祷、至诚恳切之貌。"},{term:"频巽",pinyin:["pín","xùn"],meaning:"频频勉强顺从；也通「颦」，皱着眉头装柔。"},{term:"田获三品",pinyin:["tián","huò","sān","pǐn"],meaning:"田猎获三类猎物（干豆、宾客、充庖），喻大有所获。"},{term:"先庚三日",pinyin:["xiān","gēng","sān","rì"],meaning:"庚属金、主变革；变革之前，先反复申明。"},{term:"后庚三日",pinyin:["hòu","gēng","sān","rì"],meaning:"变革之后，再反复巩固。"},{term:"无初有终",pinyin:["wú","chū","yǒu","zhōng"],meaning:"开头不顺，结局有成。"},{term:"资斧",pinyin:["zī","fǔ"],meaning:"资为钱财资本，斧为决断工具；引申为凭依与决断力。"},{term:"贞凶",pinyin:["zhēn","xiōng"],meaning:"守而不变、执着于错误的路径而致凶。"},{term:"吝"}]}),t[2]||(t[2]=o('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>巽卦讲的是<strong>以柔入物之道</strong>。上巽下巽（☴☴），两风相随，无孔不入。卦辞「巽，小亨。利有攸往，利见大人」点明：巽的亨通是「小亨」——不是大动干戈的亨，是渗透式的亨；只要柔顺得宜、往而合道，就能亨通，就能遇见该遇见的大人。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>巽教人「入」的功夫：如何让意志进入人心、如何让变革落地生根。但它最锋利的提醒是——<strong>柔顺只是手段，武人之心才是根</strong>。整卦从初六「利武人之贞」到上九「丧其资斧，贞凶」，讲的是同一件事：手段可以丢，根不可以丢。根一丢，再柔也是凶。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>优柔寡断时，先问武人之心还在不在（初六）</li><li>需要低头时，学九二——主动蛰伏 + 至诚，是智慧不是窝囊</li><li>别表演谦卑，装出来的柔撑不过第三遍（九三）</li><li>有悔就行动，用行动把悔缴获成收获（六四）</li><li>做变革，走三段式：觉察 → 行动 → 巩固（九五）</li><li>无论多柔，斧头（决断力）不能丢（上九）</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>巽卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>卦辞</td><td>小亨，利有攸往，利见大人</td><td>柔顺入物，往而合道</td><td>渗透式亨通</td></tr><tr><td>初六</td><td>进退，利武人之贞</td><td>迟疑时，用武人的果决定住</td><td>武人之心</td></tr><tr><td>九二</td><td>巽在床下，用史巫纷若，吉，无咎</td><td>主动蛰伏 + 至诚</td><td>床下是起点</td></tr><tr><td>九三</td><td>频巽，吝</td><td>别装柔，别反复</td><td>志穷之吝</td></tr><tr><td>六四</td><td>悔亡，田获三品</td><td>有悔就行动</td><td>行动改错</td></tr><tr><td>九五</td><td>贞吉，悔亡，无不利。无初有终。先庚三日后庚三日</td><td>觉察 → 行动 → 巩固</td><td>三段式变革</td></tr><tr><td>上九</td><td>巽在床下，丧其资斧，贞凶</td><td>决断力不能丢</td><td>武人之心不可丢</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>柔是手段，武人之心是根</strong>——根丢了，再柔也是凶</li><li><strong>九二 vs 上九，同辞异义</strong>——主动低伏是起点，倒下不起是放弃</li><li><strong>资斧六维</strong>——钱财、资本、凭依、工具是外力可失；决断力、行动力是内力不可夺</li><li><strong>贞凶的根源</strong>——明知答案，却不行动</li><li><strong>小亨不小</strong>——渗透式的亨，才走得远</li><li><strong>无初有终</strong>——开头难看没关系，节奏对就有好结局</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>巽卦讲的是一种「把话送进人心、把事做成风」的本事，但它在每一个关键处都敲同一个警钟：柔是手段，武人之心是根。</p><ul><li><strong>初六</strong> → 曾经的常态：进退迟疑，需要武人之贞来定</li><li><strong>九二</strong> → 现在的选择：主动蛰伏，至诚以入</li><li><strong>九三</strong> → 警惕：别把柔做成表演</li><li><strong>六四</strong> → 目标：行动，用行动让悔亡</li><li><strong>九五</strong> → 方法：觉察 → 行动 → 巩固，三段式</li><li><strong>上九</strong> → 红线：斧头（决断力）不能丢</li></ul><p>九二和上九，同一个「床下」，两种人生。主动低伏与倒下不起，表面都是「柔」，内里差一个「志」。</p><blockquote><p>金句：外力可以失去，但决断力和行动力在人身上，谁也偷不走。</p></blockquote><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：兑（第五十八卦）、涣（第五十九卦）</li><li>巽与兑的连结：巽兑相对——巽为风（入），兑为泽（说）。风入而泽应，入与说相合，才是完整的影响力：先入人心，后说出声。</li><li>巽与涣的连结：巽风之入，散开郁结；涣卦顺势解散——入得深，散得开。</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',19))])}}});export{c as __pageData,b as default};
